import { expect, test, uniqueName } from "../../fixtures";

test.describe("manage vendors", () => {
  test("the same vendor name is allowed in a different tenant", { tag: "@VEN-04" }, async ({ apiAs }) => {
    // Arrange: a vendor with the same name already exists in another tenant (Globex Procurement).
    const name = uniqueName("Acme Freight");
    const globex = await apiAs("otherTenant");
    const existing = await globex.post("/api/vendors", {
      data: { name, category: "logistics", contact_email: "ops@globex.example" },
    });
    expect(existing.status(), await existing.text()).toBe(201);

    // Act: create a vendor with that name in the signed-in member's tenant (Northwind Supply).
    const member = await apiAs("member");
    const response = await member.post("/api/vendors", {
      data: { name, category: "logistics", contact_email: "ops@acmefreight.example" },
    });

    // Assert
    expect(response.status(), await response.text()).toBe(201);
    const vendor = await response.json();
    expect(vendor.name).toBe(name);
    expect(vendor.category).toBe("logistics");
    expect(vendor.contact_email).toBe("ops@acmefreight.example");
    expect(vendor.id).not.toBe(existing.ok() ? (await existing.json()).id : undefined);
  });
});
